SELECT      c.id AS "Id do curso",     c.fullname AS "Nome do curso",     COUNT(DISTINCT ue.id) AS "Cadastrads",     COUNT(DISTINCT CASE WHEN cc.timecompleted IS NOT NULL THEN ue.id END) AS "Concluido",     COUNT(DISTINCT CASE WHEN cc.timecompleted IS NULL AND ue.status = 0 THEN ue.id END) AS "Em progresso",     COUNT(DISTINCT CASE WHEN cc.timecompleted IS NULL AND ue.status = 0 THEN ue.id END) * 100.0 / COUNT(DISTINCT ue.id) AS "Taxa de abandono",     ROUND(COUNT(DISTINCT CASE WHEN cc.timecompleted IS NOT NULL THEN ue.id END) * 100.0 / COUNT(DISTINCT ue.id), 2) AS "Taxa de conclusão",     ROUND(AVG(cc.timecompleted - ue.timecreated) / 3600, 2) AS avg_completion_time FROM      mdl_course AS c LEFT JOIN      mdl_enrol AS e ON e.courseid = c.id LEFT JOIN      mdl_user_enrolments AS ue ON ue.enrolid = e.id LEFT JOIN      mdl_course_completions AS cc ON cc.course = c.id AND cc.userid = ue.userid WHERE      c.visible = 1 GROUP BY      c.id, c.fullname ORDER BY      "Cadastrados" DESC;
